package com.picolas.openmusic;

import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.view.*;
import android.widget.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.*;
import org.junit.runner.RunWith;
import java.util.*;
import java.lang.reflect.*;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public class ProfileDeviceTest {
    @Test public void selectedPhotoIsCopiedAndPlaylistScreenRenders()throws Exception{
        Instrumentation inst=InstrumentationRegistry.getInstrumentation();Context c=inst.getTargetContext();new LocalProfile(c).finish();MusicStore store=MusicStore.get(c);long id=store.createPlaylist("Mi playlist con foto y un título largo");java.io.File source=new java.io.File(c.getFilesDir(),"cover-test.png");android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(160,120,android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(0xffff6363);try(java.io.FileOutputStream out=new java.io.FileOutputStream(source)){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();
        MainActivity activity=(MainActivity)inst.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Field target=MainActivity.class.getDeclaredField("coverTarget");target.setAccessible(true);Method save=MainActivity.class.getDeclaredMethod("savePlaylistCover",android.net.Uri.class);save.setAccessible(true);
        try{inst.runOnMainSync(()->{try{target.setLong(activity,id);save.invoke(activity,android.net.Uri.fromFile(source));}catch(Exception e){throw new RuntimeException(e);}});long end=System.currentTimeMillis()+60000;while(store.playlistField(id,"cover").isEmpty()&&System.currentTimeMillis()<end)Thread.sleep(100);String cover=store.playlistField(id,"cover");assertTrue("Selected PNG must produce a private JPEG copy",cover.startsWith("file:"));assertNotEquals(android.net.Uri.fromFile(source).toString(),cover);assertNotNull(android.graphics.BitmapFactory.decodeFile(android.net.Uri.parse(cover).getPath()));java.util.concurrent.atomic.AtomicBoolean loaded=new java.util.concurrent.atomic.AtomicBoolean();long imageDeadline=System.currentTimeMillis()+60000;while(!loaded.get()&&System.currentTimeMillis()<imageDeadline){inst.runOnMainSync(()->loaded.set(hasLoadedPhoto(activity.findViewById(android.R.id.content))));if(!loaded.get())Thread.sleep(100);}assertTrue("The chosen photo must finish loading into the visible playlist cover",loaded.get());inst.waitForIdleSync();
            inst.runOnMainSync(()->{View root=activity.findViewById(android.R.id.content);android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(root.getWidth(),root.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);root.draw(new android.graphics.Canvas(image));try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),"qa-playlist-photo.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}catch(java.io.IOException e){throw new RuntimeException(e);}finally{image.recycle();}});
        }finally{store.deletePlaylist(id);source.delete();inst.runOnMainSync(activity::finish);}
    }
    @Test public void databaseMigrationRetainsExistingPlaylist(){Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();try(SQLiteDatabase db=SQLiteDatabase.create(null)){db.execSQL("CREATE TABLE playlists (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL)");db.execSQL("INSERT INTO playlists(name) VALUES('Anterior')");MusicStore.get(c).onUpgrade(db,1,2);try(Cursor row=db.rawQuery("SELECT name,cover,description,pinned FROM playlists",null)){assertTrue(row.moveToFirst());assertEquals("Anterior",row.getString(0));assertEquals("",row.getString(1));assertEquals(0,row.getInt(3));}}}
    @Test public void playlistArtDescriptionAndOrderPersist()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();MusicStore store=MusicStore.get(c);long id=store.createPlaylist("v15 test");Track a=new Track();a.provider="youtube";a.id="aaaaaaaaaaa";a.title="Primera";Track b=new Track();b.provider="youtube";b.id="bbbbbbbbbbb";b.title="Segunda";try{store.add(id,a);store.add(id,b);store.playlistField(id,"cover","mark:4");store.playlistField(id,"description","Prueba");store.playlistField(id,"pinned","1");store.reorder(id,Arrays.asList(b,a));assertEquals(b.key(),store.playlist(id).get(0).key());assertEquals("mark:4",store.playlistField(id,"cover"));assertEquals("Prueba",store.playlistField(id,"description"));assertEquals("1",store.playlistField(id,"pinned"));}finally{store.deletePlaylist(id);}}
    private boolean hasLoadedPhoto(View view){if(view instanceof android.widget.ImageView&&!(view instanceof android.widget.ImageButton)){android.graphics.drawable.Drawable drawable=((android.widget.ImageView)view).getDrawable();if(drawable instanceof android.graphics.drawable.BitmapDrawable){android.graphics.Bitmap bitmap=((android.graphics.drawable.BitmapDrawable)drawable).getBitmap();int color=bitmap.getPixel(bitmap.getWidth()/2,bitmap.getHeight()/2);if(android.graphics.Color.red(color)>220&&android.graphics.Color.green(color)<130)return true;}}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)if(hasLoadedPhoto(group.getChildAt(i)))return true;}return false;}
    private View find(View root,Class<?> kind){if(kind.isInstance(root))return root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View result=find(group.getChildAt(i),kind);if(result!=null)return result;}}return null;}
    @Test public void firstLaunchTutorialCompletesAndIsRemembered()throws Exception{
        Instrumentation inst=InstrumentationRegistry.getInstrumentation();Context c=inst.getTargetContext();c.getSharedPreferences("local_profile",Context.MODE_PRIVATE).edit().clear().commit();
        MainActivity activity=(MainActivity)inst.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));inst.waitForIdleSync();Field field=MainActivity.class.getDeclaredField("social");field.setAccessible(true);SocialScreens screens=(SocialScreens)field.get(activity);Field wizard=SocialScreens.class.getDeclaredField("wizard");wizard.setAccessible(true);
        inst.runOnMainSync(()->{try{AlertDialog dialog=(AlertDialog)wizard.get(screens);assertNotNull(dialog);EditText input=(EditText)find(dialog.getWindow().getDecorView(),EditText.class);input.setText("Picolas test");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});inst.waitForIdleSync();
        inst.runOnMainSync(()->{try{AlertDialog dialog=(AlertDialog)wizard.get(screens);CheckBox first=(CheckBox)find(dialog.getWindow().getDecorView(),CheckBox.class);first.setChecked(true);dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});inst.waitForIdleSync();
        inst.runOnMainSync(()->{try{AlertDialog dialog=(AlertDialog)wizard.get(screens);for(int step=0;step<6;step++)dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});inst.waitForIdleSync();assertTrue("Completing the tutorial must persist onboarding",new LocalProfile(c).ready());assertEquals("Picolas test",new LocalProfile(c).name());assertTrue(new LocalProfile(c).artists().contains("Milo J"));inst.runOnMainSync(activity::finish);
    }
}
